package com.gk.jobhelper.controller;
import com.gk.jobhelper.common.ApiResponse;import com.gk.jobhelper.entity.CareerFact;import com.gk.jobhelper.service.*;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/career-facts") public class CareerFactController {private final CareerFactService facts;private final RecruitmentQualificationMatchService matches;public CareerFactController(CareerFactService f,RecruitmentQualificationMatchService m){facts=f;matches=m;}@GetMapping public ApiResponse<List<CareerFact>> list(){return ApiResponse.ok(facts.list());}@PostMapping public ApiResponse<CareerFact> save(@RequestBody CareerFact fact){return ApiResponse.ok(facts.save(fact));}@PutMapping("/{id}") public ApiResponse<CareerFact> update(@PathVariable Long id,@RequestBody CareerFact fact){fact.setId(id);return ApiResponse.ok(facts.save(fact));}@DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable Long id){facts.delete(id);return ApiResponse.ok();}@PostMapping("/confirm-and-rematch") public ApiResponse<Map<String,Long>> confirm(@RequestBody List<CareerFact> values){for(CareerFact value:values)if(value.getValueType()!=null)facts.save(value);return ApiResponse.ok(matches.rebuild());}}
